//==============================================================================================
//
//   tests/decimal_test - Decimal literals to IEEE bits
//
//   DESCRIPTION:
//       Correctly rounded conversion at every width: the audit's literals, halfway
//       points and their neighbours, the subnormal and normal boundaries, the largest
//       finite values, overflow, underflow, and long digit strings. The expected bits come
//       from exact rational arithmetic (a Fraction of the digits, rounded to the width).
//
//==============================================================================================

#include "support/decimal.h"
#include "support/literal.h"
#include "support/test.h"

#include <string>

using namespace lucb;

namespace {

uint64_t bits_of(const char* text, int width) {
    uint64_t bits = 0;
    if (!decimal_to_bits(text, width, &bits)) {
        return ~uint64_t{0};
    }
    return bits;
}

std::string repeated(char c, int n) {
    return std::string(static_cast<size_t>(n), c);
}

} // namespace

