TEST(decimal_long_digit_strings_decide_ties) {
    // one past a tie, far beyond the digit cap, still rounds up; the exact tie is even
    std::string past = "2049." + repeated('0', 900) + "1";
    CHECK(bits_of(past.c_str(), 16) == 26625ull);
    std::string tie = "2049." + repeated('0', 900);
    CHECK(bits_of(tie.c_str(), 16) == 26624ull);
    std::string huge = "1" + repeated('0', 5000);
    CHECK(bits_of(huge.c_str(), 64) == 9218868437227405312ull);
    std::string tiny = "0." + repeated('0', 5000) + "1";
    CHECK(bits_of(tiny.c_str(), 64) == 0ull);
    std::string under = "1e-" + repeated('9', 20);
    CHECK(bits_of(under.c_str(), 64) == 0ull);
    std::string over = "1e" + repeated('9', 20);
    CHECK(bits_of(over.c_str(), 32) == 2139095040ull);
}

TEST(decimal_rejects_what_is_not_a_literal) {
    CHECK(bits_of("", 64) == ~uint64_t{0});
    CHECK(bits_of(".", 64) == ~uint64_t{0});
    CHECK(bits_of("1.2.3", 64) == ~uint64_t{0});
    CHECK(bits_of("1e", 64) == ~uint64_t{0});
    CHECK(bits_of("1e+", 64) == ~uint64_t{0});
    CHECK(bits_of("1x", 64) == ~uint64_t{0});
    CHECK(bits_of("1.5", 48) == ~uint64_t{0});
    CHECK(bits_of("1_000.5", 64) == 4652011706887700480ull);
}

TEST(float_literal_value_rounds_to_the_width) {
    ParsedFloat p = parse_float_literal("16777217.00000000000000000000001f32");
    CHECK(p.ok);
    CHECK(p.body == "16777217.00000000000000000000001");
    CHECK(p.suffix == "f32");
    // binary64 keeps 16777217; binary32 rounds up to 16777218, where rounding the double
    // would have gone down to 16777216
    CHECK(float_literal_value(p, 64) == 16777217.0);
    CHECK(float_literal_value(p, 32) == 16777218.0);
    ParsedFloat h = parse_float_literal("2049.0000000000000000001");
    CHECK(float_literal_value(h, 16) == 2050.0);
    CHECK(float_literal_value(h, 64) == 2049.0);
}

TEST(hex_float_spells_bits_exactly) {
    CHECK(hex_float(0x3FF8000000000000ull, 64) == "0x1.8000000000000p+0");
    CHECK(hex_float(0, 64) == "0x0p+0");
    CHECK(hex_float(1, 64) == "0x0.0000000000001p-1022");
    CHECK(hex_float(0x7FEFFFFFFFFFFFFFull, 64) == "0x1.fffffffffffffp+1023");
    CHECK(hex_float(0x40490FDBull, 32) == "0x1.921fb6p+1f");
    CHECK(hex_float(1, 32) == "0x0.000002p-126f");
    CHECK(hex_float(0x3C00ull, 16) == "0x1.000p+0f16");
    CHECK(hex_float(1, 16) == "0x0.004p-14f16");
    CHECK(hex_float(0x7BFFull, 16) == "0x1.ffcp+15f16");
}
